import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Todo, TodoList, TodoStatus } from '../types'

// One list of todos per project, kept across sessions in $.store.
const PANE = 'todos'
const TITLE = 'Todos'
const list = atom({ plugin: 'todos', key: 'list' } as const, { root: '', items: [] })
const expanded = atom({ plugin: 'todos', key: 'expanded' } as const, [])

const MAX_DONE = 30
const storeKey = (root: string) => `list:${root}`

const GUIDE = [
  'Todos pane (the `todos` plugin): the person sees the remaining todos in a pane beside the chat, each with Do, Chat, Defer and Delete.',
  '- Keep it current: when work remains (for the person or for you), call `mcp__todos__add` with a short id, a title of a few words and a one-line summary (who, what, by when). Adding an existing id updates it.',
  '- When a todo is finished, call `mcp__todos__done` with its id and a few words on the outcome.',
  '- A prompt starting "Do [id]" came from the Do button: start that todo now. "Re [id]" is the person discussing it.',
].join('\n')

const isOpen = (t: Todo) => t.status === 'open' || t.status === 'doing'
const oneLine = (s: string | undefined, max: number) => {
  const t = (s ?? '').replace(/\s+/g, ' ').trim()
  return t.length > max ? `${t.slice(0, max - 1)}…` : t
}

// Applies `fn` to the list, keeps the done history bounded and persists it.
async function change($: EngineInterface, fn: (items: Todo[]) => Todo[]): Promise<TodoList> {
  let saved: TodoList = { root: '', items: [] }
  await update($, list, prev => {
    const items = fn(prev.items)
    const live = items.filter(t => t.status !== 'done')
    const done = items
      .filter(t => t.status === 'done')
      .sort((a, b) => b.changedAt - a.changedAt)
      .slice(0, MAX_DONE)
    saved = { root: prev.root, items: [...live, ...done] }
    return saved
  })
  await $.store.set(storeKey(saved.root), saved.items)
  return saved
}

async function setStatus($: EngineInterface, id: string, status: TodoStatus, note?: string): Promise<TodoList> {
  const now = await $.clock.now()
  return change($, items => items.map(t => (t.id === id ? { ...t, status, note: note ?? t.note, changedAt: now } : t)))
}

async function openPane($: EngineInterface) {
  return $.ui.open({ id: PANE, title: TITLE })
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const root = await $.session.root()
    const items = ((await $.store.get(storeKey(root))) as Todo[] | undefined) ?? []
    await update($, list, () => ({ root, items }))

    await $.command.register({
      name: 'todos',
      description: 'Show or hide the pane of remaining todos',
    })
    await $.tool.register({
      name: 'add',
      description:
        'Adds (or updates, by id) a remaining todo on the Todos pane, with a one-line summary. Use it whenever work remains for the person or for you.',
      inputSchema: {
        type: 'object',
        properties: {
          id: { type: 'string', description: 'Short id or slug' },
          title: { type: 'string', description: 'A few words naming the todo' },
          summary: { type: 'string', description: 'One line: who, what, by when (about 100 characters)' },
          detail: { type: 'string', description: 'Optional extra context, a line or two' },
        },
        required: ['id', 'title'],
      },
      isDeferred: false,
    })
    await $.tool.register({
      name: 'done',
      description: 'Marks a todo on the Todos pane as finished.',
      inputSchema: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          note: { type: 'string', description: 'The outcome, a few words' },
        },
        required: ['id'],
      },
      isDeferred: false,
    })
    await $.tool.register({
      name: 'list',
      description: 'Lists the todos on the Todos pane that are still open, doing or deferred.',
      isDeferred: false,
    })

    if (items.some(isOpen)) void openPane($)

    return next(e)
  })

  on('prompt.compose', async ($, e, next) => {
    const composed = await next(e)
    return {
      ...composed,
      sections: [...composed.sections, { id: 'todos:guide', text: GUIDE, scope: 'session' as const }],
    }
  })

  on('command.run', { command: 'todos' }, async $ => {
    const isUp = (await $.ui.panes()).some(p => p.id === PANE)
    if (isUp) {
      await $.ui.close({ id: PANE })
      return { text: 'Todos pane closed.' }
    }
    await openPane($)
    return { text: 'Todos pane opened.' }
  })

  on('tool.call', { tool: 'mcp__todos__add' }, async ($, e) => {
    const input = e as unknown as Partial<Todo>
    const id = oneLine(input.id, 40)
    if (!id || !input.title) return { deny: 'todos: id and title are required.' }
    const now = await $.clock.now()
    const saved = await change($, items => {
      const old = items.find(t => t.id === id)
      const item: Todo = {
        id,
        title: oneLine(input.title, 80),
        summary: input.summary ? oneLine(input.summary, 300) : old?.summary,
        detail: input.detail ? oneLine(input.detail, 600) : old?.detail,
        status: old && old.status !== 'done' ? old.status : 'open',
        addedAt: old?.addedAt ?? now,
        changedAt: now,
      }
      return old ? items.map(t => (t.id === id ? item : t)) : [...items, item]
    })
    void openPane($)
    return { result: `Added ${id} (${saved.items.filter(isOpen).length} to do).` }
  })
    .catch(() => ({ deny: 'todos: the add tool failed.' }))

  on('tool.call', { tool: 'mcp__todos__done' }, async ($, e) => {
    const { id, note } = e as unknown as { id: string; note?: string }
    const l = await read($, list)
    if (!l.items.some(t => t.id === id)) return { result: `No todo ${id} on the pane.` }
    const saved = await setStatus($, id, 'done', note ? oneLine(note, 120) : undefined)
    return { result: `Done ${id}. ${saved.items.filter(isOpen).length} left.` }
  })
    .catch(() => ({ deny: 'todos: the done tool failed.' }))

  on('tool.call', { tool: 'mcp__todos__list' }, async $ => {
    const live = (await read($, list)).items.filter(t => t.status !== 'done')
    const text = live.length
      ? live.map(t => `${t.id} (${t.status}): ${t.title}${t.summary ? ` — ${t.summary}` : ''}`).join('\n')
      : 'Nothing left to do.'
    return { result: text }
  })
    .catch(() => ({ deny: 'todos: the list tool failed.' }))

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const l = await read($, list)
    const live = l.items.filter(isOpen).sort((x, y) => x.addedAt - y.addedAt)
    const deferred = l.items.filter(t => t.status === 'deferred')
    const done = l.items.filter(t => t.status === 'done')
    const shown = new Set(await read($, expanded))
    const width = Math.max(20, (e.props.bodyColumns ?? 40) - 2)

    const toggle = (key: string) =>
      update($, expanded, keys => (keys.includes(key) ? keys.filter(k => k !== key) : [...keys, key]))
    const remove = (id: string) => change($, items => items.filter(t => t.id !== id))

    const doIt = async (t: Todo) => {
      await setStatus($, t.id, 'doing')
      void $.prompt.submit({ text: `Do [${t.id}] ${t.title}${t.summary ? `: ${t.summary}` : ''}` })
    }
    const chat = async (t: Todo) => {
      await $.prompt.fill({ text: `Re [${t.id}] ${t.title}: `, mode: 'replace' })
    }

    const header = [
      live.length === 0 ? 'Nothing left to do' : `${live.length} to do`,
      deferred.length ? `${deferred.length} deferred` : '',
    ]
      .filter(Boolean)
      .join(' · ')

    return (
      <Box flexDirection="column" gap={1}>
        <Text bold>{header}</Text>
        {live.map((t, n) => {
          const isMore = shown.has(t.id)
          return (
            <Box key={`item-${t.id}`} flexDirection="column">
              <Text bold wrap="truncate-end">
                {t.status === 'doing' ? '▶ ' : `${n + 1}. `}
                {t.title} <Text dimColor>[{t.id}]</Text>
              </Text>
              {t.summary && (
                <Text dimColor wrap={isMore ? 'wrap' : 'truncate-end'}>
                  {isMore ? t.summary : oneLine(t.summary, width * 2)}
                </Text>
              )}
              {isMore && t.detail && <Text dimColor wrap="wrap">{t.detail}</Text>}
              <Box flexDirection="row" gap={1}>
                <Button key={`do-${t.id}`} variant="primary" label={t.status === 'doing' ? 'Doing' : 'Do'} onPress={() => doIt(t)} />
                <Button key={`chat-${t.id}`} label="Chat" onPress={() => chat(t)} />
                <Button key={`defer-${t.id}`} label="Defer" onPress={() => setStatus($, t.id, 'deferred')} />
                <Button key={`delete-${t.id}`} dimColor label="Delete" onPress={() => remove(t.id)} />
                {(t.detail || (t.summary ?? '').length > width) && (
                  <Button key={`more-${t.id}`} dimColor plain label={isMore ? 'less' : 'more'} onPress={() => toggle(t.id)} />
                )}
              </Box>
            </Box>
          )
        })}
        {deferred.length > 0 && (
          <Box key="deferred" flexDirection="column">
            <Button
              key="deferred-toggle"
              dimColor
              plain
              label={`${shown.has('#deferred') ? '▾' : '▸'} Deferred (${deferred.length})`}
              onPress={() => toggle('#deferred')}
            />
            {shown.has('#deferred') &&
              deferred.map(t => (
                <Box key={`deferred-${t.id}`} flexDirection="row" gap={1}>
                  <Text dimColor wrap="truncate-end">
                    {t.title} [{t.id}]
                  </Text>
                  <Button key={`restore-${t.id}`} dimColor plain label="restore" onPress={() => setStatus($, t.id, 'open')} />
                  <Button key={`drop-${t.id}`} dimColor plain label="delete" onPress={() => remove(t.id)} />
                </Box>
              ))}
          </Box>
        )}
        {done.length > 0 && (
          <Box key="done" flexDirection="column">
            <Button
              key="done-toggle"
              dimColor
              plain
              label={`${shown.has('#done') ? '▾' : '▸'} Done (${done.length})`}
              onPress={() => toggle('#done')}
            />
            {shown.has('#done') &&
              done.map(t => (
                <Text key={`done-${t.id}`} dimColor wrap="truncate-end">
                  ✓ {t.title} [{t.id}]{t.note ? `: ${t.note}` : ''}
                </Text>
              ))}
            {shown.has('#done') && (
              <Button key="clear" dimColor plain label="clear done" onPress={() => change($, items => items.filter(x => x.status !== 'done'))} />
            )}
          </Box>
        )}
      </Box>
    )
  })
}

