export type TodoStatus = 'open' | 'doing' | 'deferred' | 'done'

export type Todo = {
  id: string
  title: string
  summary?: string
  detail?: string
  status: TodoStatus
  addedAt: number
  changedAt: number
  note?: string
}

export type TodoList = { root: string; items: Todo[] }

declare module 'claude-code' {
  interface PluginState {
    todos: { list: TodoList; expanded: string[] }
  }
}
